CREATE TABLE IF NOT EXISTS logistique (id BIGSERIAL PRIMARY KEY, reference VARCHAR(100) UNIQUE NOT NULL, designation TEXT NOT NULL, categorie VARCHAR(100), unite VARCHAR(50), quantite_stock DECIMAL(10,2) DEFAULT 0, prix_unitaire DECIMAL(15,2), fournisseur VARCHAR(255), chantier VARCHAR(255), date_entree DATE, created_at TIMESTAMPTZ DEFAULT NOW()); CREATE TABLE IF NOT EXISTS conges (id BIGSERIAL PRIMARY KEY, employe_nom TEXT, employe_id BIGINT, date_debut DATE NOT NULL, date_fin DATE NOT NULL, duree INTEGER NOT NULL, motif TEXT, statut VARCHAR(50) DEFAULT 'en_attente', created_at TIMESTAMPTZ DEFAULT NOW()); CREATE TABLE IF NOT EXISTS salaires (id BIGSERIAL PRIMARY KEY, employe_nom TEXT, employe_id BIGINT, mois INTEGER NOT NULL, annee INTEGER NOT NULL, nb_jours INTEGER DEFAULT 0, salaire_base DECIMAL(15,2), salaire_mensuel DECIMAL(15,2), net_a_payer DECIMAL(15,2), statut VARCHAR(50) DEFAULT 'calcule', created_at TIMESTAMPTZ DEFAULT NOW());
